//! Checked admission of canonical source declaration bundles.
//!
//! Input data grants no authority. Every new family is regenerated by the
//! kernel and every new value is admitted through checked add_decl. Existing
//! computational declarations must agree in both type and defining value.
//! The caller selects explicit roots; no snapshots or unchecked declarations
//! are installed. Value-free stubs use the existing checked upgrade API.

use crate::env::StoredFamilyMember;
use crate::expr::{BigNat, ExprKind, MDataValue, UsedConstants};
use crate::inductive::{ConstructorVal, InductiveVal, RecursorArgOrder, RecursorRule, RecursorVal};
use crate::{
    BinderInfo, ConstantKind, Constructor, Declaration, Environment, Expr, InductiveDecl,
    InductiveType, Level, Name, TypeChecker,
};
use serde_json::Value;
use std::collections::{BTreeSet, HashMap, HashSet};

type Result<T> = std::result::Result<T, String>;

#[cfg(test)]
#[path = "builtin_bundle_reader_tests.rs"]
mod tests;

#[path = "builtin_bundle_metadata.rs"]
mod header_metadata;

#[cfg(feature = "test-fixtures")]
impl Environment {
    /// Exercise the same checked, atomic reader as the static builtin producer.
    /// This diagnostic/test surface grants no source data additional authority.
    ///
    /// # Errors
    /// Refuses malformed records, incompatible residents, unchecked closure,
    /// new axioms, or any ordinary family/type/value checking failure.
    pub fn admit_builtin_source_for_testing(
        &mut self,
        bytes: &[u8],
        roots: &[&str],
    ) -> std::result::Result<(), super::EnvError> {
        admit(self, bytes, roots)
    }
}

fn array(v: &Value) -> Result<&[Value]> {
    v.as_array()
        .map(Vec::as_slice)
        .ok_or_else(|| "expected array".into())
}
fn text(v: &Value) -> Result<&str> {
    v.as_str().ok_or_else(|| "expected string".into())
}
fn number(v: &Value) -> Result<u32> {
    v.as_u64()
        .and_then(|n| u32::try_from(n).ok())
        .ok_or_else(|| "expected u32".into())
}
fn boolean(v: &Value) -> Result<bool> {
    v.as_bool().ok_or_else(|| "expected boolean".into())
}

/// Clean's current eager flag represents abbreviation hints and explicit
/// reducibility. Retain the full upstream fields in the source packet rather
/// than mistaking the hint alone for an environment reducibility attribute.
/// Distinct implicit/instance modes remain a declared metadata limitation.
fn definition_eager_flag(raw: &Value) -> Result<bool> {
    let hints = array(field(raw, "hints")?)?;
    let abbrev = match text(part(hints, 0)?)? {
        "abbrev" if hints.len() == 1 => true,
        "regular" if hints.len() == 2 => {
            number(part(hints, 1)?)?;
            false
        }
        _ => return Err("unsupported definition kernel hints".into()),
    };
    let explicitly_reducible = match text(field(raw, "source_reducibility")?)? {
        "[reducible]" => true,
        "[irreducible]" if !abbrev => false,
        "[irreducible]" => return Err("unsupported irreducible abbreviation policy".into()),
        "[semireducible]" | "[implicit_reducible]" | "[instance_reducible]" => false,
        _ => return Err("unsupported source reducibility status".into()),
    };
    let eager = boolean(field(raw, "reducible")?)?;
    if eager != (abbrev || explicitly_reducible) {
        return Err("inconsistent source reducibility projection".into());
    }
    Ok(eager)
}
fn field<'a>(v: &'a Value, key: &str) -> Result<&'a Value> {
    v.get(key).ok_or_else(|| format!("missing field {key}"))
}
fn part(v: &[Value], i: usize) -> Result<&Value> {
    v.get(i).ok_or_else(|| format!("missing element {i}"))
}
fn name(v: &Value, depth: usize) -> Result<Name> {
    if depth > 128 {
        return Err("name depth exceeded".into());
    }
    let v = array(v)?;
    match text(part(v, 0)?)? {
        "anon" if v.len() == 1 => Ok(Name::anon()),
        "str" if v.len() == 3 => Ok(name(part(v, 1)?, depth + 1)?.str(text(part(v, 2)?)?)),
        "num" if v.len() == 3 => {
            Ok(name(part(v, 1)?, depth + 1)?
                .num(part(v, 2)?.as_u64().ok_or("expected name number")?))
        }
        _ => Err("unknown name node".into()),
    }
}
fn names(v: &Value) -> Result<Vec<Name>> {
    array(v)?.iter().map(|v| name(v, 0)).collect()
}
fn level(v: &Value, depth: usize) -> Result<Level> {
    if depth > 256 {
        return Err("level depth exceeded".into());
    }
    let v = array(v)?;
    match text(part(v, 0)?)? {
        "zero" if v.len() == 1 => Ok(Level::zero()),
        "succ" if v.len() == 2 => Ok(Level::succ(level(part(v, 1)?, depth + 1)?)),
        "max" if v.len() == 3 => Ok(Level::max(
            level(part(v, 1)?, depth + 1)?,
            level(part(v, 2)?, depth + 1)?,
        )),
        "imax" if v.len() == 3 => Ok(Level::imax(
            level(part(v, 1)?, depth + 1)?,
            level(part(v, 2)?, depth + 1)?,
        )),
        "param" if v.len() == 2 => Ok(Level::param(name(part(v, 1)?, 0)?)),
        _ => Err("unknown level node".into()),
    }
}
fn binder(v: &Value) -> Result<BinderInfo> {
    match text(v)? {
        "default" => Ok(BinderInfo::Default),
        "implicit" => Ok(BinderInfo::Implicit),
        "strictImplicit" => Ok(BinderInfo::StrictImplicit),
        "instImplicit" => Ok(BinderInfo::InstImplicit),
        _ => Err("unknown binder annotation".into()),
    }
}
fn metadata(v: &Value) -> Result<Vec<(Name, MDataValue)>> {
    let mut result = Vec::new();
    for entry in array(v)? {
        let pair = array(entry)?;
        if pair.len() != 2 {
            return Err("invalid metadata entry".into());
        }
        let value = array(part(pair, 1)?)?;
        if value.len() != 2 {
            return Err("invalid metadata value".into());
        }
        let key = name(part(pair, 0)?, 0)?;
        // Lean.Elab.RecAppSyntax stores source Syntax solely to improve
        // termination diagnostics. Retain its complete structural payload in
        // the source artifact, and omit only that unsupported annotation
        // from the checked expression. Borrowing and all other supported
        // metadata are preserved. Unknown Syntax annotations fail closed.
        if text(part(value, 0)?)? == "recAppSyntax" {
            if key != Name::from_string("_recApp") {
                return Err("unexpected Syntax annotation".into());
            }
            array(part(value, 1)?)?;
            continue;
        }
        let data = match text(part(value, 0)?)? {
            "bool" => MDataValue::Bool(boolean(part(value, 1)?)?),
            "nat" => MDataValue::Nat(
                text(part(value, 1)?)?
                    .parse()
                    .map_err(|_| "metadata Nat exceeds u64")?,
            ),
            "string" => MDataValue::String(text(part(value, 1)?)?.into()),
            "name" => MDataValue::Name(name(part(value, 1)?, 0)?),
            _ => return Err("unsupported metadata value".into()),
        };
        result.push((key, data));
    }
    Ok(result)
}
fn reference(nodes: &[Expr], v: &Value) -> Result<Expr> {
    nodes
        .get(number(v)? as usize)
        .cloned()
        .ok_or_else(|| "forward or invalid expression reference".into())
}
fn expressions(v: &Value) -> Result<Vec<Expr>> {
    let raw = array(v)?;
    // Complete UTF-8 decoder source bundles currently use fewer than 325,000
    // nodes. Bound memory independently of the checked declaration count.
    if raw.len() > 500_000 {
        return Err("expression count exceeded".into());
    }
    let mut nodes = Vec::with_capacity(raw.len());
    for node in raw {
        let v = array(node)?;
        let at = |i| part(v, i);
        let expr = match text(at(0)?)? {
            "bvar" if v.len() == 2 => {
                let index = number(at(1)?)?;
                if index >= 1_048_575 {
                    return Err("bound variable index exceeded".into());
                }
                Expr::bvar(index)
            }
            "sort" if v.len() == 2 => Expr::sort(level(at(1)?, 0)?),
            "const" if v.len() == 3 => Expr::const_(
                name(at(1)?, 0)?,
                array(at(2)?)?
                    .iter()
                    .map(|v| level(v, 0))
                    .collect::<Result<Vec<_>>>()?,
            ),
            "app" if v.len() == 3 => {
                Expr::app(reference(&nodes, at(1)?)?, reference(&nodes, at(2)?)?)
            }
            "lam" if v.len() == 5 => {
                name(at(1)?, 0)?;
                Expr::lam(
                    binder(at(2)?)?,
                    reference(&nodes, at(3)?)?,
                    reference(&nodes, at(4)?)?,
                )
            }
            "pi" if v.len() == 5 => {
                name(at(1)?, 0)?;
                Expr::pi(
                    binder(at(2)?)?,
                    reference(&nodes, at(3)?)?,
                    reference(&nodes, at(4)?)?,
                )
            }
            "let" if v.len() == 6 => Expr::let_named(
                name(at(1)?, 0)?,
                reference(&nodes, at(2)?)?,
                reference(&nodes, at(3)?)?,
                reference(&nodes, at(4)?)?,
                at(5)?.as_bool().ok_or("expected let dependency flag")?,
            ),
            "nat" if v.len() == 2 => Expr::bignat_lit(
                BigNat::from_radix_str(text(at(1)?)?, 10).ok_or("invalid natural literal")?,
            ),
            "string" if v.len() == 2 => Expr::str_lit(text(at(1)?)?),
            "proj" if v.len() == 4 => Expr::proj(
                name(at(1)?, 0)?,
                number(at(2)?)?,
                reference(&nodes, at(3)?)?,
            ),
            "mdata" if v.len() == 3 => Expr::mdata(metadata(at(1)?)?, reference(&nodes, at(2)?)?),
            _ => return Err("unknown expression node".into()),
        };
        nodes.push(expr);
    }
    Ok(nodes)
}

fn checked_resident(env: &Environment, name: &Name) -> Result<()> {
    if env.declaration_verification(name) != Some(super::DeclarationVerification::FullKernelCheck) {
        return Err(format!("{name}: resident lacks FullKernelCheck provenance"));
    }
    if env.is_unsafe(name)
        || env.is_partial(name)
        || env.is_staged_header(name)
        || env.constant_needs_recheck(name)
    {
        return Err(format!(
            "{name}: resident is unsafe, partial, staged or needs recheck"
        ));
    }
    Ok(())
}

/// Definitional equality intentionally erases metadata. Reuse must additionally
/// preserve its positions and values, including borrowed ABI annotations.
/// The paired DAG walk permits metadata-free beta/eta differences; a changed
/// topology around metadata refuses rather than guessing an ABI equivalence.
fn metadata_agrees(left: &Expr, right: &Expr) -> bool {
    fn children(e: &Expr) -> Option<Vec<&Expr>> {
        match e.kind() {
            ExprKind::BVar(_)
            | ExprKind::FVar(_)
            | ExprKind::Sort(_)
            | ExprKind::Const(_, _)
            | ExprKind::Lit(_) => Some(vec![]),
            ExprKind::App(f, a) | ExprKind::Lam(_, f, a) | ExprKind::Pi(_, f, a) => {
                Some(vec![f, a])
            }
            ExprKind::Let(_, ty, value, body, _) => Some(vec![ty, value, body]),
            ExprKind::Proj(_, _, inner) | ExprKind::MData(_, inner) => Some(vec![inner]),
            _ => None,
        }
    }
    fn has_metadata_or_extension(e: &Expr) -> bool {
        let mut seen = HashSet::new();
        let mut pending = vec![e];
        while let Some(e) = pending.pop() {
            if !seen.insert(std::ptr::from_ref(e) as usize) {
                continue;
            }
            if matches!(e.kind(), ExprKind::MData(_, _)) {
                return true;
            }
            let Some(children) = children(e) else {
                return true;
            };
            pending.extend(children);
        }
        false
    }
    let mut seen = HashSet::new();
    let mut pending = vec![(left, right)];
    while let Some((left, right)) = pending.pop() {
        if !seen.insert((
            std::ptr::from_ref(left) as usize,
            std::ptr::from_ref(right) as usize,
        )) {
            continue;
        }
        match (left.kind(), right.kind()) {
            (ExprKind::MData(a, l), ExprKind::MData(b, r)) => {
                if a != b {
                    return false;
                }
                pending.push((l, r));
            }
            (ExprKind::App(lf, la), ExprKind::App(rf, ra)) => {
                pending.push((lf, rf));
                pending.push((la, ra));
            }
            (ExprKind::Lam(lb, lt, lv), ExprKind::Lam(rb, rt, rv))
            | (ExprKind::Pi(lb, lt, lv), ExprKind::Pi(rb, rt, rv)) => {
                if lb.info != rb.info {
                    return false;
                }
                pending.push((lt, rt));
                pending.push((lv, rv));
            }
            (ExprKind::Let(_, lt, lv, lb, _), ExprKind::Let(_, rt, rv, rb, _)) => {
                pending.push((lt, rt));
                pending.push((lv, rv));
                pending.push((lb, rb));
            }
            (ExprKind::Proj(_, _, l), ExprKind::Proj(_, _, r)) => pending.push((l, r)),
            _ => {
                if has_metadata_or_extension(left) || has_metadata_or_extension(right) {
                    return false;
                }
            }
        }
    }
    true
}

/// Audit the actual live closure, including an alternate resident proof's own
/// dependencies. Domain-axiom absence alone is not checked provenance.
fn checked_closure(env: &Environment, roots: &[Name]) -> Result<()> {
    let mut pending: BTreeSet<_> = roots.iter().cloned().collect();
    let mut seen = HashSet::new();
    while let Some(name) = pending.pop_first() {
        if !seen.insert(name.clone()) {
            continue;
        }
        checked_resident(env, &name)?;
        let info = env
            .get_const(&name)
            .ok_or_else(|| format!("resident missing: {name}"))?;
        if info.kind == ConstantKind::Axiom && !env.is_canonical_foundational_axiom(&name) {
            return Err(format!("{name}: live closure reaches a noncanonical axiom"));
        }
        let mut used = HashSet::new();
        info.type_
            .used_constants_dag(UsedConstants::WithProjectionStructures, &mut used);
        if let Some(value) = &info.value {
            value.used_constants_dag(UsedConstants::WithProjectionStructures, &mut used);
        } else if info.kind != ConstantKind::Axiom
            && (info.kind == ConstantKind::Theorem
                || (env.get_inductive(&name).is_none()
                    && env.get_constructor(&name).is_none()
                    && env.get_recursor(&name).is_none()
                    && env.get_quot(&name).is_none()))
        {
            return Err(format!(
                "{name}: resident proof or computational value absent"
            ));
        }
        if let Some(inductive) = env.get_inductive(&name) {
            used.extend(inductive.all_names.iter().cloned());
            used.extend(inductive.constructor_names.iter().cloned());
        }
        if let Some(constructor) = env.get_constructor(&name) {
            used.insert(constructor.inductive_name.clone());
        }
        if let Some(recursor) = env.get_recursor(&name) {
            used.insert(recursor.inductive_name.clone());
            for rule in &recursor.rules {
                used.insert(rule.constructor_name.clone());
                rule.rhs
                    .used_constants_dag(UsedConstants::WithProjectionStructures, &mut used);
            }
        }
        pending.extend(used);
    }
    Ok(())
}

#[derive(Clone)]
struct Candidate {
    raw: Value,
    name: Name,
    levels: Vec<Name>,
    kind: String,
    ty: Expr,
    value: Option<Expr>,
    header: header_metadata::HeaderMetadata,
}
struct Admission {
    env: Environment,
    nodes: Vec<Expr>,
    candidates: HashMap<Name, Candidate>,
    visiting: HashSet<Name>,
    complete: HashSet<Name>,
}
impl Admission {
    fn dependencies(&mut self, e: &Expr, skip: &[Name]) -> Result<()> {
        let mut used = HashSet::new();
        e.used_constants_dag(UsedConstants::WithProjectionStructures, &mut used);
        let mut used: Vec<_> = used.into_iter().collect();
        used.sort();
        for dep in used {
            if !skip.contains(&dep) {
                self.admit(&dep)?;
            }
        }
        Ok(())
    }
    fn compare_existing(&self, c: &Candidate) -> Result<bool> {
        let Some(old) = self.env.get_const(&c.name) else {
            return Ok(false);
        };
        // Import-mode prelude stubs are never evidence for a source value.
        // The caller checks their dependencies and invokes the existing
        // checked upgrade API, which compares types and validates the body.
        if old.kind == ConstantKind::Axiom
            && old.value.is_none()
            && matches!(c.kind.as_str(), "definition" | "theorem" | "opaque")
        {
            return Ok(false);
        }
        checked_resident(&self.env, &c.name)?;
        if self.env.is_noncomputable(&c.name) != c.header.is_noncomputable() {
            return Err(format!("{}: existing noncomputable policy differs", c.name));
        }
        let debt = self
            .env
            .axiom_deps(&c.name)
            .ok_or("missing axiom closure")?;
        if !debt.is_empty() {
            return Err(format!(
                "{}: existing declaration reaches non-foundational axioms: {debt:?}",
                c.name
            ));
        }
        if c.kind == "axiom" && !self.env.is_canonical_foundational_axiom(&c.name) {
            return Err(format!(
                "{}: only existing canonical foundational axioms may be reused",
                c.name
            ));
        }
        if old.level_params.len() != c.levels.len() {
            return Err(format!("{}: existing universe arity differs", c.name));
        }
        let subst: Vec<_> = c
            .levels
            .iter()
            .cloned()
            .zip(old.level_params.iter().cloned().map(Level::param))
            .collect();
        let ty = c.ty.instantiate_level_params(&subst);
        let tc = TypeChecker::new(&self.env);
        if !tc.is_def_eq(&old.type_, &ty) {
            return Err(format!("{}: existing type differs", c.name));
        }
        if !metadata_agrees(&old.type_, &ty) {
            return Err(format!(
                "{}: existing type binder/metadata policy differs",
                c.name
            ));
        }
        match c.kind.as_str() {
            "definition" | "opaque" => {
                let expected_kind = if c.kind == "opaque" {
                    ConstantKind::Opaque
                } else {
                    ConstantKind::Definition
                };
                if old.kind != expected_kind {
                    return Err(format!(
                        "{}: existing definition/opaque kind differs",
                        c.name
                    ));
                }
                if c.kind == "definition"
                    && (old.is_reducible != definition_eager_flag(&c.raw)?
                        || if c.header.is_irreducible() {
                            old.reducibility != super::Reducibility::Irreducible
                        } else {
                            !matches!(
                                old.reducibility,
                                super::Reducibility::Reducible | super::Reducibility::Regular(_)
                            )
                        })
                {
                    return Err(format!(
                        "{}: existing definition reducibility policy differs",
                        c.name
                    ));
                }
                let value = c
                    .value
                    .as_ref()
                    .ok_or("missing candidate value")?
                    .instantiate_level_params(&subst);
                let old_value = old
                    .value
                    .as_ref()
                    .ok_or_else(|| format!("{}: existing value absent", c.name))?;
                if !tc.is_def_eq(old_value, &value) {
                    return Err(format!("{}: existing computational body differs", c.name));
                }
                if !metadata_agrees(old_value, &value) {
                    return Err(format!(
                        "{}: existing computational binder/metadata policy differs",
                        c.name
                    ));
                }
            }
            "theorem" => {
                if old.value.is_none() {
                    return Err(format!("{}: existing proof absent", c.name));
                }
            }
            "inductive" => {
                let old = self
                    .env
                    .get_inductive(&c.name)
                    .ok_or("existing constant is not inductive")?;
                let stored = InductiveVal {
                    name: c.name.clone(),
                    level_params: old.level_params.clone(),
                    type_: ty,
                    num_params: number(field(&c.raw, "parameters")?)?,
                    num_indices: number(field(&c.raw, "indices")?)?,
                    all_names: names(field(&c.raw, "all")?)?,
                    constructor_names: names(field(&c.raw, "constructors")?)?,
                    is_recursive: boolean(field(&c.raw, "recursive")?)?,
                    is_reflexive: boolean(field(&c.raw, "reflexive")?)?,
                    is_nested: boolean(field(&c.raw, "nested")?)?,
                    is_large_elim: old.is_large_elim,
                };
                self.env
                    .lean_replay_compare_stored_member(StoredFamilyMember::Inductive(&stored))
                    .map_err(|e| format!("{e}\nsource: {}\nresident: {}\nsource-debug: {:?}\nresident-debug: {:?}", stored.type_, old.type_, stored.type_, old.type_))?;
            }
            "constructor" => {
                let old = self
                    .env
                    .get_constructor(&c.name)
                    .ok_or("existing constant is not a constructor")?;
                let stored = ConstructorVal {
                    name: c.name.clone(),
                    level_params: old.level_params.clone(),
                    type_: ty,
                    inductive_name: name(field(&c.raw, "inductive")?, 0)?,
                    constructor_idx: number(field(&c.raw, "index")?)?,
                    num_params: number(field(&c.raw, "parameters")?)?,
                    num_fields: number(field(&c.raw, "fields")?)?,
                };
                self.env
                    .lean_replay_compare_stored_member(StoredFamilyMember::Constructor(&stored))
                    .map_err(|e| {
                        format!("{e}\nsource: {}\nresident: {}", stored.type_, old.type_)
                    })?;
            }
            "recursor" => {
                let old = self
                    .env
                    .get_recursor(&c.name)
                    .ok_or("existing constant is not a recursor")?;
                let all = names(field(&c.raw, "all")?)?;
                if !all.contains(&old.inductive_name) {
                    return Err("recursor family differs".into());
                }
                let mut rules = Vec::new();
                for rule in array(field(&c.raw, "rules")?)? {
                    let num_fields = number(field(rule, "fields")?)?;
                    rules.push(RecursorRule {
                        constructor_name: name(field(rule, "constructor")?, 0)?,
                        num_fields,
                        recursive_fields: vec![false; num_fields as usize],
                        rhs: reference(&self.nodes, field(rule, "rhs")?)?
                            .instantiate_level_params(&subst),
                    });
                }
                let stored = RecursorVal {
                    name: c.name.clone(),
                    level_params: old.level_params.clone(),
                    type_: ty,
                    inductive_name: old.inductive_name.clone(),
                    arg_order: RecursorArgOrder::MajorAfterMinors,
                    num_params: number(field(&c.raw, "parameters")?)?,
                    num_indices: number(field(&c.raw, "indices")?)?,
                    num_motives: number(field(&c.raw, "motives")?)?,
                    num_minors: number(field(&c.raw, "minors")?)?,
                    rules,
                    is_k: boolean(field(&c.raw, "k")?)?,
                };
                self.env
                    .lean_replay_compare_stored_member(StoredFamilyMember::Recursor(&stored))
                    .map_err(|e| e.to_string())?;
            }
            "axiom" => {}
            "quotient" => {
                if self.env.get_quot(&c.name).is_none()
                    || !self.env.is_canonical_foundational_axiom(&c.name)
                {
                    return Err(format!(
                        "{}: existing canonical quotient primitive required",
                        c.name
                    ));
                }
            }
            _ => return Err(format!("unsupported declaration kind {}", c.kind)),
        }
        Ok(true)
    }
    fn admit(&mut self, name: &Name) -> Result<()> {
        if self.complete.contains(name) {
            return Ok(());
        }
        let c = self
            .candidates
            .get(name)
            .cloned()
            .ok_or_else(|| format!("dependency absent from bundle: {name}"))?;
        if !self.visiting.insert(name.clone()) {
            return Err(format!("cyclic non-family dependency: {name}"));
        }
        if c.kind == "constructor" || c.kind == "recursor" {
            let parent = if c.kind == "constructor" {
                name_from_field(&c.raw, "inductive")?
            } else {
                names(field(&c.raw, "all")?)?
                    .first()
                    .cloned()
                    .ok_or("empty recursor family")?
            };
            self.admit(&parent)?;
            if !self.compare_existing(&c)? {
                return Err(format!("kernel did not generate {name}"));
            }
        } else if c.kind == "inductive" {
            let all = names(field(&c.raw, "all")?)?;
            let mut types = Vec::new();
            for ty in &all {
                let ty = self
                    .candidates
                    .get(ty)
                    .cloned()
                    .ok_or("missing mutual member")?;
                self.dependencies(&ty.ty, &all)?;
                let mut constructors = Vec::new();
                for ctor_name in names(field(&ty.raw, "constructors")?)? {
                    let ctor = self
                        .candidates
                        .get(&ctor_name)
                        .cloned()
                        .ok_or("missing constructor")?;
                    self.dependencies(&ctor.ty, &all)?;
                    constructors.push(Constructor {
                        name: ctor.name,
                        type_: ctor.ty,
                    });
                }
                types.push(InductiveType {
                    name: ty.name,
                    type_: ty.ty,
                    constructors,
                });
            }
            if !self.compare_existing(&c)? {
                self.env
                    .add_inductive_core(InductiveDecl {
                        level_params: c.levels.clone(),
                        num_params: number(field(&c.raw, "parameters")?)?,
                        types,
                    })
                    .map_err(|e| format!("{name}: {e}"))?;
            }
            for ty in &all {
                self.complete.insert(ty.clone());
                let ty = self
                    .candidates
                    .get(ty)
                    .cloned()
                    .ok_or("missing mutual member")?;
                if !self.compare_existing(&ty)? {
                    return Err("kernel did not generate family member".into());
                }
                for ctor in names(field(&ty.raw, "constructors")?)? {
                    let ctor = self.candidates.get(&ctor).ok_or("missing constructor")?;
                    if !self.compare_existing(ctor)? {
                        return Err("kernel did not generate constructor".into());
                    }
                    self.complete.insert(ctor.name.clone());
                }
            }
            let mut recursors = Vec::new();
            for candidate in self.candidates.values() {
                if candidate.kind == "recursor" && names(field(&candidate.raw, "all")?)? == all {
                    recursors.push(candidate.clone());
                }
            }
            for recursor in recursors {
                if !self.compare_existing(&recursor)? {
                    return Err(format!("kernel did not generate {}", recursor.name));
                }
                self.complete.insert(recursor.name);
            }
        } else {
            self.dependencies(&c.ty, &[])?;
            if c.kind == "theorem" {
                let tc = TypeChecker::new(&self.env);
                let sort = tc.infer_type_full(&c.ty).map_err(|e| e.to_string())?;
                if !tc.is_def_eq(&sort, &Expr::prop()) {
                    return Err(format!("{}: theorem type is not a proposition", c.name));
                }
            }
            // A resident checked proof of the same proposition is sufficient:
            // proof irrelevance permits its own foundational-only proof term.
            // Computational definitions still traverse and compare their value.
            if c.kind == "theorem" && self.compare_existing(&c)? {
                self.visiting.remove(name);
                self.complete.insert(name.clone());
                return Ok(());
            }
            if let Some(value) = &c.value {
                self.dependencies(value, &[])?;
            }
            if !self.compare_existing(&c)? {
                let value = || c.value.clone().ok_or("missing value".to_string());
                let decl = match c.kind.as_str() {
                    "definition" => Declaration::Definition {
                        name: c.name.clone(),
                        level_params: c.levels.clone(),
                        type_: c.ty.clone(),
                        value: value()?,
                        is_reducible: definition_eager_flag(&c.raw)?,
                    },
                    "theorem" => Declaration::Theorem {
                        name: c.name.clone(),
                        level_params: c.levels.clone(),
                        type_: c.ty.clone(),
                        value: value()?,
                    },
                    "opaque" => Declaration::Opaque {
                        name: c.name.clone(),
                        level_params: c.levels.clone(),
                        type_: c.ty.clone(),
                        value: value()?,
                    },
                    _ => {
                        return Err(format!(
                            "new axiom or unsupported declaration refused: {name}"
                        ))
                    }
                };
                if self
                    .env
                    .get_const(name)
                    .is_some_and(|info| info.kind == ConstantKind::Axiom && info.value.is_none())
                {
                    self.env.upgrade_axiom_to_checked_decl(decl)
                } else {
                    self.env.add_decl(decl)
                }
                .map_err(|e| format!("{name}: {e}"))?;
            }
        }
        self.visiting.remove(name);
        self.complete.insert(name.clone());
        Ok(())
    }
}
fn name_from_field(v: &Value, field_name: &str) -> Result<Name> {
    name(field(v, field_name)?, 0)
}

/// Admit a statically selected set of source declarations atomically.
/// Every family and value crosses the ordinary checked kernel APIs. No
/// successfully checked prefix is visible if a later record fails.
pub(super) fn admit(
    env: &mut Environment,
    bytes: &[u8],
    roots: &[&str],
) -> std::result::Result<(), super::EnvError> {
    let staged = admit_inner(env.clone(), bytes, roots)
        .map_err(|detail| super::EnvError::BuiltinBundle { detail })?;
    *env = staged;
    Ok(())
}

fn admit_inner(env: Environment, bytes: &[u8], roots: &[&str]) -> Result<Environment> {
    if bytes.len() > 32 * 1024 * 1024 {
        return Err("bundle size exceeded".into());
    }
    let json: Value = serde_json::from_slice(bytes).map_err(|e| e.to_string())?;
    if text(field(&json, "schema")?)? != "clean-checked-declaration-dag-3" {
        return Err("unsupported schema".into());
    }
    let normalizations = serde_json::json!([{
        "key": ["str", ["anon"], "_recApp"],
        "valueKind": "Syntax",
        "action": "omit-from-kernel-mdata",
        "scope": "post-elaboration recursion source diagnostics only"
    }, {
        "kind": "declaration-reducibility",
        "source": ["hints", "source_reducibility"],
        "action": "kernel-abbrev-or-explicit-reducible-to-eager-flag",
        "remaining": "distinct implicit/instance statuses retained but not installed by this reader"
    }]);
    if field(&json, "normalizations")? != &normalizations {
        return Err("unsupported or unrecorded metadata normalization".into());
    }
    let nodes = expressions(field(&json, "expressions")?)?;
    let allowed: HashSet<_> = names(field(&json, "roots")?)?.into_iter().collect();
    let roots: Vec<_> = roots.iter().map(|root| Name::from_string(root)).collect();
    if roots.iter().any(|root| !allowed.contains(root)) {
        return Err("requested root absent from bundle root contract".into());
    }
    let mut candidates = HashMap::new();
    let raw_nodes = array(field(&json, "expressions")?)?;
    for raw in array(field(&json, "declarations")?)? {
        let candidate = Candidate {
            name: name_from_field(raw, "name")?,
            levels: names(field(raw, "levels")?)?,
            kind: text(field(raw, "kind")?)?.into(),
            ty: reference(&nodes, field(raw, "type")?)?,
            value: raw
                .get("value")
                .map(|value| reference(&nodes, value))
                .transpose()?,
            header: header_metadata::read(raw, raw_nodes)?,
            raw: raw.clone(),
        };
        if candidates
            .insert(candidate.name.clone(), candidate)
            .is_some()
        {
            return Err("duplicate declaration".into());
        }
    }
    let mut admission = Admission {
        env,
        nodes,
        candidates,
        visiting: HashSet::new(),
        complete: HashSet::new(),
    };
    for root in &roots {
        admission.admit(root)?;
        let debt = admission
            .env
            .axiom_deps(root)
            .ok_or("missing root axiom closure")?;
        if !debt.is_empty() {
            return Err(format!(
                "{root}: source root reaches non-foundational axioms: {debt:?}"
            ));
        }
    }
    checked_closure(&admission.env, &roots)?;
    for name in &admission.complete {
        let candidate = admission
            .candidates
            .get(name)
            .ok_or("missing checked source metadata")?;
        candidate
            .header
            .install(&mut admission.env, name, candidate.kind == "definition")?;
    }
    Ok(admission.env)
}
